    private var cameraX=0f;private var cameraY=0f;private var cameraScale=1f;private var cameraRotation=0f;private val samples=mutableListOf<Stabilizer.Sample>();private var current:Path?=null;private var lastPoint:PointF?=null;private var lastTime=0L;private val lasso=mutableListOf<PointF>();private val selectedStrokeIds=mutableSetOf<String>();private var gestureStart:PointF?=null;private val ui=Paint(Paint.ANTI_ALIAS_FLAG);private val bitmapCache=HashMap<String,Bitmap>()
