    private fun bg(c:Canvas){ui.style=Paint.Style.FILL;ui.color=Color.rgb(16,17,19);c.drawRect(0f,0f,width.toFloat(),height.toFloat(),ui)}
    private fun drawHome(c:Canvas){bg(c);ui.color=Color.rgb(27,29,32);c.drawRect(0f,0f,width.toFloat(),54f,ui);text(c,"ANIMA-ME",22f,35f,Color.WHITE,18f);text(c,"Sort by date",width-115f,35f,Color.LTGRAY,10f);if(ProjectStore.projects.isEmpty())text(c,"No projects",width/2f-35f,height/2f,Color.LTGRAY,14f)else{var y=80f;ProjectStore.projects.forEach{p->ui.color=Color.rgb(36,39,43);c.drawRoundRect(24f,y,300f,y+150f,8f,8f,ui);text(c,p.name,40f,y+122f,Color.WHITE,12f);text(c,"${p.fps} fps   ${p.cameraWidth} x ${p.cameraHeight}",40f,y+141f,Color.GRAY,9f);y+=170f}};ui.color=Color.rgb(52,55,60);c.drawRoundRect(width-190f,height-76f,width-24f,height-26f,10f,10f,ui);text(c,"New project",width-154f,height-45f,Color.WHITE,12f)}
    private fun drawEditor(c:Canvas){bg(c);val w=width.toFloat();val h=height.toFloat();ui.color=Color.rgb(27,29,32);c.drawRect(0f,0f,w,50f,ui);text(c,"☰",18f,34f,Color.WHITE,24f);text(c,"ANIMA-ME",52f,32f,Color.WHITE,15f);text(c,project?.name?:"Untitled",150f,32f,Color.LTGRAY,12f);text(c,"${document.fps} FPS",w-72f,32f,Color.LTGRAY,10f);ui.color=selectedColor;c.drawRoundRect(w-170f,12f,w-136f,38f,5f,5f,ui);ui.style=Paint.Style.STROKE;ui.color=Color.WHITE;ui.strokeWidth=1f;c.drawRoundRect(w-170f,12f,w-136f,38f,5f,5f,ui);ui.style=Paint.Style.FILL
